using System; using System.Linq; using System.Security.Cryptography;
namespace OrderFlow.MVC.Security { public static class PasswordHasher { private const int Iterations = 100000; public static string Hash(string password, out string salt) { var saltBytes = new byte[16]; using (var rng = RandomNumberGenerator.Create()) rng.GetBytes(saltBytes); salt = Convert.ToBase64String(saltBytes); using (var pbkdf2 = new Rfc2898DeriveBytes(password, saltBytes, Iterations, HashAlgorithmName.SHA256)) return Convert.ToBase64String(pbkdf2.GetBytes(32)); } public static bool Verify(string password, string storedHash, string storedSalt) { var salt = Convert.FromBase64String(storedSalt); using (var pbkdf2 = new Rfc2898DeriveBytes(password, salt, Iterations, HashAlgorithmName.SHA256)) { var candidate = pbkdf2.GetBytes(32); var expected = Convert.FromBase64String(storedHash); return candidate.Length == expected.Length && candidate.Zip(expected, (a, b) => a == b).All(x => x); } } } }
